#define EXIT_ERROR_CODE 1

// Child process terminates immediately
if (fork() == 0) {
    // Standard I/O buffers are NOT flushed
    // atexit() handlers are NOT called
    _exit(EXIT_ERROR_CODE); 
}

// Parent waits for status
int status;
wait(&status);
// WEXITSTATUS(status) retrieves EXIT_ERROR_CODE (1)

// Alternative form (C99 standard equivalent)
if (some_error) {
    _Exit(EXIT_ERROR_CODE);
}
